30	  const tmpDirs: string[] = [];
31	
32	  function createTempDir(): string {
33	    const dir = join(
34	      tmpdir(),
35	      'agentrack-wt-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
36	    );
37	    mkdirSync(dir, { recursive: true });
38	    tmpDirs.push(dir);
39	    return realpathSync(dir);
40	  }
41	
42	  function createGitRepo(dir: string): string {
43	    execSync('git init', { cwd: dir, stdio: 'ignore' });
44	    execSync('git config user.email test@test.com', { cwd: dir, stdio: 'ignore' });
45	    execSync('git config user.name Test', { cwd: dir, stdio: 'ignore' });
46	    writeFileSync(join(dir, 'README.md'), '# Test\n');
47	    execSync('git add .', { cwd: dir, stdio: 'ignore' });
48	    execSync('git commit -m initial', { cwd: dir, stdio: 'ignore' });
49	    return dir;
50	  }
